#include <iostream>
#include <limits>

bool convertir_a_int(long long dato, int& destino) {
    // Este inicio solo comprueba el extremo superior.
    const long long maximo =
        static_cast<long long>(std::numeric_limits<int>::max());
    if (dato > maximo) {
        return false;
    }

    destino = static_cast<int>(dato);
    return true;
}

int main() {
    int caso = 0;
    if (!(std::cin >> caso)) {
        return 1;
    }

    const long long minimo =
        static_cast<long long>(std::numeric_limits<int>::lowest());
    const long long maximo =
        static_cast<long long>(std::numeric_limits<int>::max());
    if (minimo == std::numeric_limits<long long>::lowest()
        || maximo == std::numeric_limits<long long>::max()) {
        return 2;
    }

    long long dato = 0;
    int esperado = 17;

    switch (caso) {
    case 1:
        dato = minimo - 1;
        break;
    case 2:
        dato = minimo;
        esperado = std::numeric_limits<int>::lowest();
        break;
    case 3:
        dato = -42;
        esperado = -42;
        break;
    case 4:
        dato = 0;
        esperado = 0;
        break;
    case 5:
        dato = 42;
        esperado = 42;
        break;
    case 6:
        dato = maximo;
        esperado = std::numeric_limits<int>::max();
        break;
    case 7:
        dato = maximo + 1;
        break;
    default:
        return 1;
    }

    int destino = 17;
    const bool aceptado = convertir_a_int(dato, destino);

    std::cout << "Aceptado=" << aceptado << '\n';
    std::cout << "Coincide=" << (destino == esperado) << '\n';
    std::cout << "Conservado=" << (destino == 17) << '\n';

    return 0;
}

